grep '^cpu[0-2] ' /proc/stat; ( /tmp/rt-audit-tools/rtload mem 2 60 > /tmp/rt-audit-run/MEM-load.txt 2>&1 & lm=$!; echo "$lm" > /tmp/rt-audit-run/MEM-load.pid; /tmp/rt-audit-tools/cyclictest --laptop -a1 -t1 -p80 --policy=fifo -m -i1000 -D60 -q -h2000 > /tmp/rt-audit-run/MEM.txt 2>&1; c=$?; wait "$lm"; a=$?; printf '%s %s\n' "$c" "$a" > /tmp/rt-audit-run/MEM.rc ) & echo "MEM_WRAPPER_PID=$!"; cat /proc/uptime
